import React, { useEffect } from "react";
import { SEO } from "../components/common/SEO";
import { logout } from "../ppm/openbase/openbase";

const LogoutPage: React.FC = () => {
  useEffect(() => {
    if (typeof window === "undefined") return;

    async function doLogout() {
      // Clear in-memory + localStorage token. logout() is currently sync
      // but we await it so any future async cleanup (revoke calls, etc.)
      // completes before we redirect.
      await logout();

      // Hard navigation rather than gatsby's navigate(). Without this, the
      // /login page's useOpenbase hook can race against the just-completed
      // logout — it reads the in-memory _token before our state propagates,
      // sees the user as authed, and bounces them to /dashboard.
      // window.location.replace forces a full page load so the JS module
      // re-initializes with _token = null and localStorage already cleared.
      window.location.replace("/login");
    }
    doLogout();
  }, []);

  return (
    <div style={{ minHeight: "100vh", display: "flex", alignItems: "center", justifyContent: "center", background: "#f0f2f5" }}>
      <p style={{ fontSize: 18, color: "#555" }}>Logging out…</p>
    </div>
  );
};

export const Head = () => (
  <SEO
    title="Logging Out"
    description="You are being logged out."
    canonical="/logout/"
    noIndex
  />
)
export default LogoutPage;
